[
  {
    "version": "v0.9",
    "type": "createSurface",
    "surface": {
      "id": "tokyo-itinerary",
      "type": "modal"
    },
    "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
  },
  {
    "version": "v0.9",
    "type": "updateComponents",
    "surfaceId": "tokyo-itinerary",
    "components": [
      {
        "id": "root",
        "type": "Column",
        "properties": {
          "children": [
            {
              "id": "header_main",
              "type": "Header",
              "properties": {
                "title": "Tokyo Itinerary Summary: Anime, Temples & Ramen",
                "level": 3
              }
            },
            {
              "id": "text_intro",
              "type": "Text",
              "properties": {
                "text": "This 3-day plan balances Tokyo's vibrant pop culture with its serene traditions. You'll explore the electric streets of Akihabara, the historic grounds of Asakusa, and the bustling hub of Shinjuku, all while enjoying some of the city's best ramen."
              }
            },
            {
              "id": "text_assumptions",
              "type": "Text",
              "properties": {
                "text": "This itinerary assumes you are staying in a central Tokyo location and are comfortable with walking. The budget is per person and covers food, local transport, and activities, but excludes shopping and accommodation. All prices are estimates.",
                "textStyle": "caption"
              }
            },
            {
              "id": "card_budget_total",
              "type": "Card",
              "properties": {
                "child": {
                  "id": "row_budget_total",
                  "type": "Row",
                  "properties": {
                    "children": [
                      {
                        "id": "icon_budget_total",
                        "type": "Icon",
                        "properties": {
                          "icon": "/budget",
                          "size": "large"
                        }
                      },
                      {
                        "id": "col_budget_total",
                        "type": "Column",
                        "properties": {
                          "children": [
                            {
                              "id": "text_budget_label",
                              "type": "Text",
                              "properties": {
                                "text": "Total Estimated Budget:",
                                "textStyle": "label"
                              }
                            },
                            {
                              "id": "text_budget_value",
                              "type": "Text",
                              "properties": {
                                "text": "**30,000 - 35,000 JPY** (well under the 45,000 JPY limit for 3 days)"
                              }
                            }
                          ]
                        }
                      }
                    ]
                  }
                }
              }
            },
            {
              "id": "tabs_main",
              "type": "Tabs",
              "properties": {
                "tabs": [
                  {
                    "label": "Pre-Travel",
                    "childId": "col_pre_travel"
                  },
                  {
                    "label": "Day 1",
                    "childId": "col_day1"
                  },
                  {
                    "label": "Day 2",
                    "childId": "col_day2"
                  },
                  {
                    "label": "Day 3",
                    "childId": "col_day3"
                  }
                ]
              }
            },
            {
              "id": "divider_quick_actions",
              "type": "Divider"
            },
            {
              "id": "row_quick_actions",
              "type": "Row",
              "properties": {
                "horizontalAlignment": "spaceEvenly",
                "children": [
                  {
                    "id": "button_suica",
                    "type": "Button",
                    "properties": {
                      "label": "Get a Suica Card",
                      "action": {
                        "type": "functionCall",
                        "call": "openUrl",
                        "args": {
                          "url": "https://www.jreast.co.jp/multi/en/pass/suica.html"
                        }
                      }
                    }
                  },
                  {
                    "id": "button_tripadvisor",
                    "type": "Button",
                    "properties": {
                      "label": "Explore Tokyo on TripAdvisor",
                      "action": {
                        "type": "functionCall",
                        "call": "openUrl",
                        "args": {
                          "url": "https://www.tripadvisor.com/Tourism"
                        }
                      }
                    }
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "id": "col_pre_travel",
        "type": "Column",
        "properties": {
          "children": [
            {
              "id": "header_pre_travel",
              "type": "Header",
              "properties": {
                "title": "Pre-Travel Checklist"
              }
            },
            {
              "id": "list_pre_travel",
              "type": "List",
              "properties": {
                "children": [
                  {
                    "id": "item_transport",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Transport Card",
                      "secondaryText": "Purchase a Suica or Pasmo card at the airport or a major train station for seamless travel.",
                      "startComponentId": "check_transport"
                    }
                  },
                  {
                    "id": "item_connectivity",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Connectivity",
                      "secondaryText": "Rent a pocket Wi-Fi device or get a travel SIM card for navigation.",
                      "startComponentId": "check_connectivity"
                    }
                  },
                  {
                    "id": "item_cash",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Cash",
                      "secondaryText": "Carry at least 10,000 JPY in cash for smaller shops, stalls, and vendors.",
                      "startComponentId": "check_cash"
                    }
                  },
                  {
                    "id": "item_hours",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Check Opening Times",
                      "secondaryText": "Use Google Maps to verify opening hours for attractions and restaurants before you go.",
                      "startComponentId": "check_hours"
                    }
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "id": "check_transport",
        "type": "Checkbox"
      },
      {
        "id": "check_connectivity",
        "type": "Checkbox"
      },
      {
        "id": "check_cash",
        "type": "Checkbox"
      },
      {
        "id": "check_hours",
        "type": "Checkbox"
      },
      {
        "id": "col_day1",
        "type": "Column",
        "properties": {
          "children": [
            {
              "id": "header_day1",
              "type": "Header",
              "properties": {
                "title": "Day 1: Modern Tokyo & Anime Mecca",
                "subtitle": "2025-05-10, Saturday"
              }
            },
            {
              "id": "text_day1_focus",
              "type": "Text",
              "properties": {
                "text": "**Focus:** Youth culture, iconic cityscapes, and the heart of anime/gaming."
              }
            },
            {
              "id": "card_day1_morning",
              "type": "Card",
              "properties": {
                "child": {
                  "id": "col_day1_morning",
                  "type": "Column",
                  "properties": {
                    "children": [
                      {
                        "id": "header_day1_morning",
                        "type": "Header",
                        "properties": {
                          "title": "Morning (9:00 AM - 1:00 PM)",
                          "subtitle": "Harajuku & Meiji Shrine"
                        }
                      },
                      {
                        "id": "row_day1_m1",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day1_m1",
                              "type": "Icon",
                              "properties": {
                                "icon": "/activity"
                              }
                            },
                            {
                              "id": "text_day1_m1",
                              "type": "Text",
                              "properties": {
                                "text": "Start at **Meiji Jingu Shrine**, a peaceful oasis dedicated to Emperor Meiji."
                              }
                            }
                          ]
                        }
                      },
                      {
                        "id": "row_day1_m2",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day1_m2",
                              "type": "Icon",
                              "properties": {
                                "icon": "/activity"
                              }
                            },
                            {
                              "id": "text_day1_m2",
                              "type": "Text",
                              "properties": {
                                "text": "Walk to **Harajuku's Takeshita Street** to experience youth fashion and try a famous crepe."
                              }
                            }
                          ]
                        }
                      },
                      {
                        "id": "row_day1_m3",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day1_m3",
                              "type": "Icon",
                              "properties": {
                                "icon": "/travel"
                              }
                            },
                            {
                              "id": "text_day1_m3",
                              "type": "Text",
                              "properties": {
                                "text": "Take the JR Yamanote Line to Harajuku Station."
                              }
                            }
                          ]
                        }
                      }
                    ]
                  }
                }
              }
            },
            {
              "id": "card_day1_afternoon",
              "type": "Card",
              "properties": {
                "child": {
                  "id": "col_day1_afternoon",
                  "type": "Column",
                  "properties": {
                    "children": [
                      {
                        "id": "header_day1_afternoon",
                        "type": "Header",
                        "properties": {
                          "title": "Afternoon (1:00 PM - 5:00 PM)",
                          "subtitle": "Shibuya's Scramble"
                        }
                      },
                      {
                        "id": "image_shibuya",
                        "type": "Image",
                        "properties": {
                          "src": "/shibuya",
                          "alt": "The bustling Shibuya Crossing intersection from above."
                        }
                      },
                      {
                        "id": "row_day1_a1",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day1_a1",
                              "type": "Icon",
                              "properties": {
                                "icon": "/food"
                              }
                            },
                            {
                              "id": "text_day1_a1",
                              "type": "Text",
                              "properties": {
                                "text": "Grab lunch in the Harajuku/Omotesando area."
                              }
                            }
                          ]
                        }
                      },
                      {
                        "id": "row_day1_a2",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day1_a2",
                              "type": "Icon",
                              "properties": {
                                "icon": "/travel"
                              }
                            },
                            {
                              "id": "text_day1_a2",
                              "type": "Text",
                              "properties": {
                                "text": "Walk or take the JR Yamanote Line one stop to Shibuya."
                              }
                            }
                          ]
                        }
                      },
                      {
                        "id": "row_day1_a3",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day1_a3",
                              "type": "Icon",
                              "properties": {
                                "icon": "/activity"
                              }
                            },
                            {
                              "id": "text_day1_a3",
                              "type": "Text",
                              "properties": {
                                "text": "Witness the famous **Shibuya Crossing** and visit the Hachiko Statue."
                              }
                            }
                          ]
                        }
                      }
                    ]
                  }
                }
              }
            },
            {
              "id": "card_day1_evening",
              "type": "Card",
              "properties": {
                "child": {
                  "id": "col_day1_evening",
                  "type": "Column",
                  "properties": {
                    "children": [
                      {
                        "id": "header_day1_evening",
                        "type": "Header",
                        "properties": {
                          "title": "Evening (5:00 PM onwards)",
                          "subtitle": "Akihabara Electric Town"
                        }
                      },
                      {
                        "id": "image_akihabara",
                        "type": "Image",
                        "properties": {
                          "src": "/akihabara",
                          "alt": "The neon-lit streets of Akihabara Electric Town at night."
                        }
                      },
                      {
                        "id": "row_day1_e1",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day1_e1",
                              "type": "Icon",
                              "properties": {
                                "icon": "/travel"
                              }
                            },
                            {
                              "id": "text_day1_e1",
                              "type": "Text",
                              "properties": {
                                "text": "Take the JR Yamanote Line from Shibuya to Akihabara Station."
                              }
                            }
                          ]
                        }
                      },
                      {
                        "id": "row_day1_e2",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day1_e2",
                              "type": "Icon",
                              "properties": {
                                "icon": "/activity"
                              }
                            },
                            {
                              "id": "text_day1_e2",
                              "type": "Text",
                              "properties": {
                                "text": "Dive into the world of anime, manga, and gaming. Explore arcades and figure shops."
                              }
                            }
                          ]
                        }
                      },
                      {
                        "id": "row_day1_e3",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day1_e3",
                              "type": "Icon",
                              "properties": {
                                "icon": "/food"
                              }
                            },
                            {
                              "id": "text_day1_e3",
                              "type": "Text",
                              "properties": {
                                "text": "Dinner is your first high-end ramen experience in Akihabara."
                              }
                            }
                          ]
                        }
                      }
                    ]
                  }
                }
              }
            },
            {
              "id": "card_day1_budget",
              "type": "Card",
              "properties": {
                "child": {
                  "id": "col_day1_budget",
                  "type": "Column",
                  "properties": {
                    "children": [
                      {
                        "id": "header_day1_budget",
                        "type": "Header",
                        "properties": {
                          "title": "Daily Budget Breakdown (Est.)"
                        }
                      },
                      {
                        "id": "list_day1_budget",
                        "type": "List",
                        "properties": {
                          "children": [
                            {
                              "id": "item_day1_b1",
                              "type": "ListItem",
                              "properties": {
                                "primaryText": "Travel",
                                "endComponentId": "text_day1_b1_val"
                              }
                            },
                            {
                              "id": "item_day1_b2",
                              "type": "ListItem",
                              "properties": {
                                "primaryText": "Food",
                                "endComponentId": "text_day1_b2_val"
                              }
                            },
                            {
                              "id": "item_day1_b3",
                              "type": "ListItem",
                              "properties": {
                                "primaryText": "Activities",
                                "endComponentId": "text_day1_b3_val"
                              }
                            },
                            {
                              "id": "item_day1_b4",
                              "type": "ListItem",
                              "properties": {
                                "primaryText": "Total",
                                "endComponentId": "text_day1_b4_val"
                              }
                            }
                          ]
                        }
                      }
                    ]
                  }
                }
              }
            },
            {
              "id": "text_day1_b1_val",
              "type": "Text",
              "properties": {
                "text": "1,000 JPY"
              }
            },
            {
              "id": "text_day1_b2_val",
              "type": "Text",
              "properties": {
                "text": "6,000 JPY"
              }
            },
            {
              "id": "text_day1_b3_val",
              "type": "Text",
              "properties": {
                "text": "2,000 JPY"
              }
            },
            {
              "id": "text_day1_b4_val",
              "type": "Text",
              "properties": {
                "text": "**~9,000 JPY**"
              }
            },
            {
              "id": "card_day1_ramen",
              "type": "Card",
              "properties": {
                "child": {
                  "id": "col_day1_ramen",
                  "type": "Column",
                  "properties": {
                    "children": [
                      {
                        "id": "header_day1_ramen",
                        "type": "Header",
                        "properties": {
                          "title": "Ramen Spotlight: Day 1"
                        }
                      },
                      {
                        "id": "image_ramen_1",
                        "type": "Image",
                        "properties": {
                          "src": "/ramen",
                          "alt": "A delicious bowl of premium Japanese ramen."
                        }
                      },
                      {
                        "id": "card_ramen_1_1",
                        "type": "Card",
                        "properties": {
                          "child": {
                            "id": "col_ramen_1_1",
                            "type": "Column",
                            "properties": {
                              "children": [
                                {
                                  "id": "text_ramen_1_1_name",
                                  "type": "Text",
                                  "properties": {
                                    "text": "**Motenashi Kuroki**"
                                  }
                                },
                                {
                                  "id": "text_ramen_1_1_desc",
                                  "type": "Text",
                                  "properties": {
                                    "text": "Shio (salt-based) ramen with delicate, complex flavors. Approx. 2,000 JPY"
                                  }
                                },
                                {
                                  "id": "button_ramen_1_1",
                                  "type": "Button",
                                  "properties": {
                                    "label": "Map/Info",
                                    "action": {
                                      "type": "functionCall",
                                      "call": "openUrl",
                                      "args": {
                                        "url": "#"
                                      }
                                    }
                                  }
                                }
                              ]
                            }
                          }
                        }
                      },
                      {
                        "id": "card_ramen_1_2",
                        "type": "Card",
                        "properties": {
                          "child": {
                            "id": "col_ramen_1_2",
                            "type": "Column",
                            "properties": {
                              "children": [
                                {
                                  "id": "text_ramen_1_2_name",
                                  "type": "Text",
                                  "properties": {
                                    "text": "**Kikanbo, Akihabara**"
                                  }
                                },
                                {
                                  "id": "text_ramen_1_2_desc",
                                  "type": "Text",
                                  "properties": {
                                    "text": "Spicy Miso ramen with customizable spice levels. A fiery and unforgettable bowl. Approx. 1,800 JPY"
                                  }
                                },
                                {
                                  "id": "button_ramen_1_2",
                                  "type": "Button",
                                  "properties": {
                                    "label": "Map/Info",
                                    "action": {
                                      "type": "functionCall",
                                      "call": "openUrl",
                                      "args": {
                                        "url": "#"
                                      }
                                    }
                                  }
                                }
                              ]
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            }
          ]
        }
      },
      {
        "id": "col_day2",
        "type": "Column",
        "properties": {
          "children": [
            {
              "id": "header_day2",
              "type": "Header",
              "properties": {
                "title": "Day 2: Tradition & Culture",
                "subtitle": "2025-05-11, Sunday"
              }
            },
            {
              "id": "text_day2_focus",
              "type": "Text",
              "properties": {
                "text": "**Focus:** Historic temples, traditional markets, and sweeping city views."
              }
            },
            {
              "id": "card_day2_morning",
              "type": "Card",
              "properties": {
                "child": {
                  "id": "col_day2_morning",
                  "type": "Column",
                  "properties": {
                    "children": [
                      {
                        "id": "header_day2_morning",
                        "type": "Header",
                        "properties": {
                          "title": "Morning (9:00 AM - 1:00 PM)",
                          "subtitle": "Asakusa's Senso-ji Temple"
                        }
                      },
                      {
                        "id": "image_sensoji",
                        "type": "Image",
                        "properties": {
                          "src": "/sensoji",
                          "alt": "The iconic red lantern of the Kaminarimon gate at Senso-ji Temple."
                        }
                      },
                      {
                        "id": "row_day2_m1",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day2_m1",
                              "type": "Icon",
                              "properties": {
                                "icon": "/travel"
                              }
                            },
                            {
                              "id": "text_day2_m1",
                              "type": "Text",
                              "properties": {
                                "text": "Take the Tokyo Metro Ginza Line to Asakusa Station."
                              }
                            }
                          ]
                        }
                      },
                      {
                        "id": "row_day2_m2",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "icon_day2_
